    if (!hasYesterdayAccomplishment || !hasTodayPlan || !hasChallenges) {
      return {
        email_sent: false,
        reason: "incomplete_report_data",
      };
    }
  
    // すべてのバリデーションを通過した場合、メール送信成功を返す
    return {
      email_sent: true,
    };
